import{z as l,x as n,o as r,c as p,q as i,j as o,D as t,d as e,s as A,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Dijkstra 互斥","description":"","frontmatter":{"title":"Dijkstra 互斥","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dijkstra-mutex.md","filePath":"cs/dijkstra-mutex.md","lastUpdated":1791063341000}'),d={name:"cs/dijkstra-mutex.md"};function c(m,a,D,h,k,C){const s=n("Mermaid");return r(),p("div",null,[a[2]||(a[2]=i('<h1 id="dijkstra-互斥" tabindex="-1">Dijkstra 互斥 <a class="header-anchor" href="#dijkstra-互斥" aria-label="Permalink to &quot;Dijkstra 互斥&quot;">​</a></h1><div class="epigraph"><p>并发进程要合作使用临界资源；互斥、进展与有限等待可以先写成命题，再谈锁的实现。</p><footer>—— Dijkstra, Solution of a Problem in Concurrent Programming Control, CACM 1965；对照 EWD 与信号量后来的讲义</footer></div><p><a href="/cs/knuth-taocp">上一课</a>附录对照了顺序算法的分析。附录对照，不插入主干。主干已在<a href="/cs/knuth-taocp">竞争与临界区</a>、<a href="/cs/lock-irq">锁与关中断</a>、<a href="/cs/semaphore">信号量</a>里用过临界区；这里对照 <strong>1965 短文的问题</strong>：不靠特殊原子指令以外的「谁先写标志」，能否正确互斥。不重做 Peterson 的逐行证明。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Knuth 式分析默认单线程步数。一旦两个控制流交错，<a href="/cs/loop-invariant">循环不变式</a>要对所有交错成立。Dijkstra 1965 针对的是临界区：一次至多一个进程在里面。后来的信号量、管程是同一问题的抽象升级，主干已经分开上课。附录只对照原文把互斥当成可发表的正确性问题。</p><p><span class="marginnote">直觉类比：临界区像单人试衣间——互斥要求同一时刻只进一人；进展要求试衣间空着时，想用的人不能被保安拦住；有限等待要求排队的人最多等有限轮就轮到。三条合起来才是合格的门禁协议。</span></p><p><span class="marginnote">Dekker 算法更早；Dijkstra 把问题陈述标准化。硬件原子（test-and-set）把实现变简单，但不取消「临界区规格」。主干锁课用关中断与原子，1965 文更在软件标志。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写出互斥、无死锁、公平性一类命题，给共享变量协议。主干用锁 API 把协议藏进内核；附录对照：规格先于 <code>lock()</code> 这个词。信号量（Dijkstra 后来的 P/V）把睡与醒做成原语，主干信号量课已取用。</p><p><span class="marginnote">术语翻译：test-and-set 是硬件用一条指令完成「读旧值、写新值」且中间不可被打断。1965 文靠纯软件标志互相试探，要绕开各种交错陷阱；有了原子指令实现大幅缩短，但「临界区规格」本身一个字不变。</span></p>',10)),(r(),o(B,null,{default:t(()=>[A(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RACE%5B%22%E4%BA%A4%E9%94%99%22%5D%20--%3E%20CS%5B%22%E4%B8%B4%E7%95%8C%E5%8C%BA%E8%A7%84%E6%A0%BC%22%5D%0A%20%20CS%20--%3E%20MUTEX%5B%22%E4%BA%92%E6%96%A5%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20CS%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E9%94%81%20%2F%20%E4%BF%A1%E5%8F%B7%E9%87%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("一旦互斥是命题，死锁四条件、管程、数据库 2PL 都是同一家族在不同对象上的投影。1965 文不管持久化、不管分布式故障。数据库"),E("a",{href:"/cs/db-deadlock"},"库内死锁"),e("课已经声明与 OS 同构；本附录不把 2PL 写回 1965。")],-1)),a[5]||(a[5]=E("p",null,"上面那张图画 1965 文在课序里的对照位置；这张给出审读任何互斥协议的检查单：三个条件按顺序问，每个条件违反时是什么症状。",-1)),(r(),o(B,null,{default:t(()=>[A(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%8B%BF%E5%88%B0%E4%B8%80%E4%B8%AA%E4%B8%A4%E8%BF%9B%E7%A8%8B%E5%8D%8F%E8%AE%AE%22%5D%20--%3E%20C1%5B%22%E6%A3%80%E6%9F%A51%20%E4%BA%92%E6%96%A5%20%E8%83%BD%E5%90%A6%E5%90%8C%E6%97%B6%E8%BF%9B%22%5D%0A%20%20C1%20--%20%22%E8%83%BD%22%20--%3E%20BUG1%5B%22%E4%B8%A4%E4%BA%BA%E9%83%BD%E5%9C%A8%E4%B8%B4%E7%95%8C%E5%8C%BA%20%E6%95%B0%E6%8D%AE%E8%A2%AB%E5%86%99%E5%9D%8F%22%5D%0A%20%20C1%20--%20%22%E4%B8%8D%E8%83%BD%22%20--%3E%20C2%5B%22%E6%A3%80%E6%9F%A52%20%E8%BF%9B%E5%B1%95%20%E7%A9%BA%E9%97%B2%E6%97%B6%E6%83%B3%E8%BF%9B%E7%9A%84%E6%98%AF%E5%90%A6%E8%A2%AB%E6%8B%A6%22%5D%0A%20%20C2%20--%20%22%E6%98%AF%22%20--%3E%20BUG2%5B%22%E9%94%81%E7%A9%BA%E7%9D%80%20%E5%A4%A7%E5%AE%B6%E5%B9%B2%E7%AD%89%22%5D%0A%20%20C2%20--%20%22%E5%90%A6%22%20--%3E%20C3%5B%22%E6%A3%80%E6%9F%A53%20%E6%9C%89%E9%99%90%E7%AD%89%E5%BE%85%20%E6%98%AF%E5%90%A6%E6%9C%89%E4%BA%BA%E6%B0%B8%E8%BF%9C%E6%8E%92%E4%B8%8D%E4%B8%8A%22%5D%0A%20%20C3%20--%20%22%E6%98%AF%22%20--%3E%20BUG3%5B%22%E9%A5%A5%E9%A5%BF%20%E6%9F%90%E8%BF%9B%E7%A8%8B%E8%A2%AB%E9%A5%BF%E6%AD%BB%22%5D%0A%20%20C3%20--%20%22%E5%90%A6%22%20--%3E%20OK%5B%22%E5%8D%8F%E8%AE%AE%E5%90%88%E6%A0%BC%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">常见误区：以为协议「试跑一亿次没坏」就算正确。并发正确性要求对所有可能交错成立——最坏的交错可能百万次才出现一次，还只在特定缓存时序下露头。这正是 Dijkstra 把它写成数学命题、用不变式而不是测试来钉死的原因。</span></p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>若把 1965 插在线程课之前当第一课并发，读者会先学 Dekker 再学进程。主干先有进程映像与调度，再有竞争。附录只对照「并发正确性可以先写规格」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1968 年 THE 系统与 1965 短文混成一篇。也不要在此展开线性化与内存模型——主干<a href="/cs/memory-consistency">存储一致性</a>另有位置。下一篇对照 Lamport 1978 如何在没有共享内存的机器上谈「先于」。</p><p>饥饿与公平是 1965 文之后逐步写清的；主干锁课用「进展」而不是把公平算法插进第一课同步。</p><p>对照结束应回到主干<a href="/cs/race-critical">竞争与临界区</a>与<a href="/cs/semaphore">信号量</a>。1965 短文不插入进程映像之前。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>附录对照，不插入主干。</p></li><li><p>下一篇对照 Lamport 1978 逻辑时钟。</p></li><li><p>附录对照 Dijkstra 1965：临界区作为可证明的合作问题。</p></li><li><p>主干锁与信号量课已取用规格；本篇不插入线程课之前。</p></li><li><p>无共享内存的次序是 Lamport 时钟附录。</p></li><li><p>出处：Dijkstra, <em>CACM</em> 8(9), 1965。</p></li></ul>',9))])}const F=l(d,[["render",c]]);export{f as __pageData,F as default};
